sketch.css:
.ti{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:12px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.ti *{box-sizing:border-box}
.head{display:flex;justify-content:space-between;align-items:flex-start}
.totals{display:flex;gap:20px}
.tot .tl{color:var(--muted);font-size:11.5px;font-weight:500}
.tot .tv{font-size:20px;font-weight:700;letter-spacing:-.01em;line-height:1.2}
.tot .tv small{font-size:12px;font-weight:500;color:var(--muted);margin-left:3px}
.tot.alert .tv{color:var(--red)}
.units{display:flex;gap:2px;background:var(--background);border-radius:8px;padding:2px}
.unit{padding:2px 9px;border-radius:6px;font-size:11.5px;font-weight:500;color:var(--muted);cursor:pointer}
.unit:hover{color:var(--text)}
.unit.selected{background:var(--window);color:var(--accent);box-shadow:0 1px 2px rgba(20,20,50,.1)}
.tanks{flex:1;display:flex;gap:10px;min-height:0}
.tank{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:5px;padding:6px 4px 8px;border-radius:10px;cursor:pointer;border:1px solid transparent}
.tank:hover{background:var(--hover)}
.tank.selected{background:var(--hover);border-color:var(--accent)}
.slot{height:16px;display:flex;align-items:center}
.badge{font-size:10px;font-weight:700;padding:0 6px;border-radius:8px;color:var(--window);background:var(--c)}
.vessel{position:relative;flex:1;width:64px;min-height:80px;border:2px solid var(--border);border-radius:14px 14px 8px 8px;background:var(--background);overflow:hidden}
.liquid{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(180deg,color-mix(in srgb,var(--c) 70%,white),var(--c));transition:height .3s}
.liquid:before{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:color-mix(in srgb,white 45%,transparent)}
.mark{position:absolute;left:-2px;right:-2px;height:0;border-top:1.5px dashed var(--m)}
.mark span{position:absolute;right:3px;top:-12px;font-size:9px;font-weight:600;color:var(--m)}
.pct{position:absolute;left:0;right:0;top:50%;transform:translateY(-50%);text-align:center;font-weight:700;font-size:14px;color:var(--text);text-shadow:0 0 4px var(--window)}
.name{font-weight:600;font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.qty{font-size:12px;font-variant-numeric:tabular-nums;white-space:nowrap}
.meta{display:flex;gap:6px;font-size:11px;color:var(--muted);white-space:nowrap}
.flow.in{color:var(--green);font-weight:600}
.flow.out{color:var(--amber);font-weight:600}
.empty{flex:1;color:var(--muted);text-align:center;padding:30px 0}

