function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const unit = props.unit || 'bbl';
  const f = unit === 'gal' ? 42 : 1;                     // levels are kept in barrels
  const fmt = v => { v = v * f; return v >= 1e6 ? (v / 1e6).toFixed(2) + 'M' : v >= 1e4 ? Math.round(v / 1e3) + 'k' : Math.round(v).toLocaleString(); };
  const tanks = props.tanks || [];

  // totals
  let onHand = 0, cap = 0, alarms = 0, cover = 0;
  tanks.forEach(t => {
    onHand += +t.level || 0; cap += +t.capacity || 0; cover += +t.daysCover || 0;
    const p = t.capacity ? t.level / t.capacity * 100 : 0;
    if (p <= (+t.low || 0) || p >= (+t.high || 100)) alarms++;
  });
  root.querySelector('.totals').innerHTML =
    '<div class="tot"><div class="tl">On hand</div><div class="tv">' + fmt(onHand) + '<small>' + unit + '</small></div></div>' +
    '<div class="tot"><div class="tl">Utilization</div><div class="tv">' + (cap ? Math.round(onHand / cap * 100) : 0) + '<small>%</small></div></div>' +
    '<div class="tot"><div class="tl">Avg days of cover</div><div class="tv">' + (tanks.length ? (cover / tanks.length).toFixed(1) : '0') + '</div></div>' +
    '<div class="tot' + (alarms ? ' alert' : '') + '"><div class="tl">Alarms</div><div class="tv">' + alarms + '</div></div>';

  // unit switch
  const us = root.querySelector('.units');
  us.innerHTML = ['bbl', 'gal'].map(u => '<span class="unit' + (u === unit ? ' selected' : '') + '" data-u="' + u + '">' + u + '</span>').join('');
  us.querySelectorAll('.unit').forEach(el => el.onclick = () => { if (el.dataset.u !== unit) fire('unitChanged', { unit: el.dataset.u }); });

  // tanks
  const box = root.querySelector('.tanks');
  if (!tanks.length) { box.innerHTML = '<div class="empty">No tanks</div>'; return; }
  box.innerHTML = tanks.map(t => {
    const p = Math.max(0, Math.min(100, t.capacity ? t.level / t.capacity * 100 : 0));
    const low = +t.low || 0, high = +t.high || 100;
    const state = p <= low ? 'low' : p >= high ? 'high' : 'ok';
    const c = state === 'low' ? 'var(--red)' : state === 'high' ? 'var(--amber)' : 'var(--sky)';
    const flow = +t.netFlow || 0;
    const marks = props.showAlarms === false ? '' :
      '<div class="mark" style="--m:var(--amber);bottom:' + high + '%"><span>H</span></div>' +
      '<div class="mark" style="--m:var(--red);bottom:' + low + '%"><span>L</span></div>';
    return '<div class="tank' + (t.id === props.selected ? ' selected' : '') + '" data-id="' + esc(t.id) + '" style="--c:' + c + '">' +
      '<div class="slot">' + (state !== 'ok' ? '<span class="badge">' + (state === 'low' ? 'LOW' : 'HIGH') + '</span>' : '') + '</div>' +
      '<div class="vessel"><div class="liquid" style="height:' + p + '%"></div>' + marks + '<div class="pct">' + Math.round(p) + '%</div></div>' +
      '<div class="name" title="' + esc(t.terminal) + '">' + esc(t.terminal) + '</div>' +
      '<div class="qty"><b>' + fmt(+t.level || 0) + '</b> / ' + fmt(+t.capacity || 0) + '</div>' +
      '<div class="meta"><span>' + (+t.daysCover || 0).toFixed(1) + 'd cover</span>' +
      '<span class="flow ' + (flow >= 0 ? 'in' : 'out') + '">' + (flow >= 0 ? '▲' : '▼') + fmt(Math.abs(flow)) + '</span></div>' +
      '</div>';
  }).join('');
  box.querySelectorAll('.tank').forEach(el => el.onclick = () => fire('tankSelected', { id: el.dataset.id, selected: el.dataset.id }));
}
